import 'package:cli_tools/cli_tools.dart';

void main() async {
  final runner = BetterCommandRunner('my_cli', 'Example CLI');
  runner.addCommand(EchoCommand());
  await runner.run(arguments);
}

class EchoCommand extends Command {
  @override final name = 'echo';
  @override final description = 'Prints the given text.';
  EchoCommand() { argParser.addOption('text', abbr: 't'); }
  @override void run() => print(argResults!['text']);
}
